// TargetsForPrincipal is the resolver for the targetsForPrincipal field.
func (r *queryResolver) TargetsForPrincipal(ctx context.Context, query *string, connectionID *string) ([]*MachineTarget, error) {
	resp, err := r.Vault.ListTargets(ctx, &vaultv1.ListTargetsRequest{Actor: resolvers.MachineActorOf(ctx)})
	if err != nil {
		return nil, err
	}
	q := strings.ToLower(deref(query))
	out := make([]*MachineTarget, 0, len(resp.GetTargets()))
	for _, t := range resp.GetTargets() {
		if connectionID != nil && t.GetConnectionId() != *connectionID {
			continue
		}
		if q != "" && !strings.Contains(strings.ToLower(t.GetName()+" "+t.GetHostname()+" "+t.GetDomain()), q) {
			continue
		}
		out = append(out, targetOf(t))
	}
	return out, nil
}

