// Automation is the resolver for the automation field. Vault's response
// carries the secret but not the new type's capabilities, so the catalog is
// read here, and only when the caller selects automation.
func (r *typeChangedSecretResolver) Automation(ctx context.Context, obj *TypeChangedSecret) (*TypeChangeAutomation, error) {
	resp, err := r.Vault.ListSecretTypes(ctx, &vaultv1.ListSecretTypesRequest{})
	if err != nil {
		return nil, err
	}
	for _, t := range resp.GetTypes() {
		if t.GetId() == obj.Secret.TypeID {
			return typeChangeAutomationOf(t, obj.Secret), nil
		}
	}
	return nil, fmt.Errorf("secret type %q is not in the catalog", obj.Secret.TypeID)
}

